using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;

namespace DailyDiaryCard;
public static class SelfTests
{
    public static int Run(string root,string template)
    {
        root=Path.GetFullPath(root);Directory.CreateDirectory(root);
        var real=DiarySession.ReadText(template);var originalHash=DiarySession.Hash(real);var results=new List<object>();int failures=0,index=0;
        var date=new DateOnly(2026,10,24);
        var expectedTitles=System.Text.RegularExpressions.Regex.Matches(real,@"(?m)^##[ \t]+([^\r\n]+)").Select(m=>m.Groups[1].Value.Trim()).ToArray();
        CardConfig Fixture()
        {
            var dir=Path.Combine(root,(++index).ToString("00"));Directory.CreateDirectory(Path.Combine(dir,".obsidian"));Directory.CreateDirectory(Path.Combine(dir,"模板"));File.WriteAllText(Path.Combine(dir,"模板","真实模板.md"),real,new UTF8Encoding(false));
            File.WriteAllText(Path.Combine(dir,".obsidian","daily-notes.json"),"{\"folder\":\"日记\",\"format\":\"YYYY/MM/YYYY-MM-DD\",\"template\":\"模板/真实模板\"}");
            var config=Path.Combine(dir,"test-config.json");File.WriteAllText(config,JsonSerializer.Serialize(new CardConfig{VaultPath=dir,UserDataPath=Path.Combine(dir,"local")},CardConfig.Json));return CardConfig.Load(config);
        }
        void Assert(bool ok,string message="断言失败"){if(!ok)throw new Exception(message);}
        void Test(string name,Action run){try{run();results.Add(new{name,passed=true});}catch(Exception e){failures++;results.Add(new{name,passed=false,error=e.ToString()});}}
        void ExpectFailure(Action run){bool failed=false;try{run();}catch(IOException){failed=true;}catch(UnauthorizedAccessException){failed=true;}Assert(failed,"应该停止写入，但没有报错");}
        string First(DiarySession s)=>s.Template[0].Title;
        void Change(DiarySession s,string text="中文编辑：你好，今天有新的进展。\n")=>s.Edit(First(s),s.Bodies[First(s)]+text);
        void Seed(CardConfig c,string? text=null){Directory.CreateDirectory(Path.GetDirectoryName(c.PathFor(date))!);File.WriteAllText(c.PathFor(date),text??real.Replace("{{date:YYYY-MM-DD}}","2026-10-24"),new UTF8Encoding(false));}

        Test("真实模板：当前栏目、顺序和三级归属",()=>{var d=new MarkdownDoc(real);Assert(d.Sections.Select(s=>s.Title).SequenceEqual(expectedTitles));Assert(d.Sections[0].Title=="每日任务完成情况");Assert(d.Sections.Last().Title=="第二日任务规划");Assert(d.Sections[0].Body.Contains("### 今日临时任务"));});
        Test("动态标题：不硬编码栏目，排除代码与注释伪标题",()=>{var d=new MarkdownDoc("---\nx: |\n  ## YAML\n---\n## 动态新栏\n### 子栏\n```md\n## 代码\n```\n<!--\n## 注释\n-->\n## 次栏\n中文");Assert(d.Sections.Select(s=>s.Title).SequenceEqual(new[]{"动态新栏","次栏"}));});
        Test("只读启动不创建当天文件",()=>{var c=Fixture();var s=new DiarySession(c,date);Assert(!File.Exists(s.Target));Assert(!s.Dirty);});
        Test("首次编辑创建、替换日期并保留 YAML 与任务标记",()=>{var c=Fixture();var s=new DiarySession(c,date);Change(s);s.Save();var text=DiarySession.ReadText(s.Target);Assert(text.Contains("journal_date: \"2026-10-24\""));Assert(!text.Contains("{{date:"));Assert(text.Contains("type: diary")&&text.Contains("tags:")&&text.Contains("<!-- TASKS:START -->")&&text.Contains("<!-- TASKS:END -->"));});
        Test("持续更新同一文件，无副本及临时残留",()=>{var c=Fixture();var s=new DiarySession(c,date);Change(s);s.Save();Change(s,"第二次\n");s.Save();Assert(Directory.GetFiles(c.DiaryFolder,"*.md",SearchOption.AllDirectories).Length==1);Assert(Directory.GetFiles(c.DiaryFolder,"*.tmp",SearchOption.AllDirectories).Length==0);Assert(DiarySession.ReadText(s.Target).Contains("第二次"));});
        Test("重新建立会话恢复已保存中文",()=>{var c=Fixture();var s=new DiarySession(c,date);Change(s);s.Save();var restarted=new DiarySession(c,date);Assert(restarted.Bodies[First(s)]==s.Bodies[First(s)]&&!restarted.Dirty);});
        Test("任务勾选往返保持有效 Markdown",()=>{var c=Fixture();var s=new DiarySession(c,date);s.Edit(First(s),s.Bodies[First(s)].Replace("- [ ]","- [x]"));s.Save();var again=new DiarySession(c,date);Assert(again.Bodies[First(s)].Contains("- [x]"));Assert(again.Bodies[First(s)].Contains("### 今日临时任务"));});
        Test("首版不新增任务承接",()=>{var c=Fixture();var previous=c.PathFor(date.AddDays(-1));Directory.CreateDirectory(Path.GetDirectoryName(previous)!);File.WriteAllText(previous,"## 第二日任务规划\n- [ ] 昨日独有任务123\n");var s=new DiarySession(c,date);Change(s);s.Save();Assert(!DiarySession.ReadText(s.Target).Contains("昨日独有任务123"));});
        Test("跨天初始化：无输入也生成日期模板并保持已保存",()=>{var c=Fixture();var s=new DiarySession(c,date);s.EnsureDailyFile();Assert(File.Exists(s.Target)&&!s.Dirty);var text=DiarySession.ReadText(s.Target);Assert(!text.Contains("{{date:")&&text.Contains("journal_date: \"2026-10-24\""));Assert(text.Contains("<!-- TASKS:START -->")&&new MarkdownDoc(text).Sections.Count==expectedTitles.Length);});
        Test("跨天初始化：已有笔记逐字保留并匹配栏目",()=>{var c=Fixture();var original=real.Replace("{{date:YYYY-MM-DD}}","2026-10-24").Replace("type: diary","type: diary\ncustom: 已有属性")+"\n## 额外栏目\n已有日记内容\n";Seed(c,original);var s=new DiarySession(c,date);s.EnsureDailyFile();Assert(DiarySession.ReadText(s.Target)==original&&s.Bodies.Count==expectedTitles.Length&&!s.Dirty);});
        Test("跨天初始化：其他程序先创建时载入而不覆盖",()=>{var c=Fixture();var s=new DiarySession(c,date);var external=real.Replace("{{date:YYYY-MM-DD}}","2026-10-24").Replace("前一天规划的任务会自动放在这里","外部先创建的当天任务");Seed(c,external);s.EnsureDailyFile();Assert(DiarySession.ReadText(s.Target)==external&&s.Bodies[First(s)].Contains("外部先创建"));});
        Test("跨天初始化失败：阻塞路径不留下临时稿",()=>{var c=Fixture();var s=new DiarySession(c,date);Directory.CreateDirectory(s.Target);ExpectFailure(s.EnsureDailyFile);Assert(Directory.Exists(s.Target)&&Directory.GetFiles(Path.GetDirectoryName(s.Target)!,"*.tmp").Length==0);});
        Test("跨天初始化：已读文件被删除时不重建覆盖",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);File.Delete(s.Target);ExpectFailure(s.EnsureDailyFile);Assert(!File.Exists(s.Target));});
        Test("已有笔记的未知 YAML 与其他章节保护",()=>{var c=Fixture();var initial=real.Replace("{{date:YYYY-MM-DD}}","2026-10-24").Replace("type: diary","type: diary\ncustom: 保留我")+"\n## 额外栏目\n已有中文内容\n";Seed(c,initial);var s=new DiarySession(c,date);Change(s);s.Save();var text=DiarySession.ReadText(s.Target);Assert(text.Contains("custom: 保留我")&&text.EndsWith("## 额外栏目\n已有中文内容\n"));});
        Test("外部修改其他栏目和 YAML：三方合并",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);Change(s);var second=s.Template[1];var other=new MarkdownDoc(s.Baseline!).Apply(new(){{second.Title,"\n外部新内容\n\n"}},s.Template).Replace("type: diary","type: diary\nexternal: 保留");File.WriteAllText(s.Target,other,new UTF8Encoding(false));s.Save();var text=DiarySession.ReadText(s.Target);Assert(text.Contains("外部新内容")&&text.Contains("中文编辑")&&text.Contains("external: 保留"));Assert(s.Bodies[second.Title].Contains("外部新内容"));});
        Test("同栏冲突不覆盖磁盘，保留草稿与输入",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);Change(s);var external=new MarkdownDoc(s.Baseline!).Apply(new(){{First(s),s.Bodies[First(s)]+"外部同时修改\n"}},s.Template);File.WriteAllText(s.Target,external,new UTF8Encoding(false));ExpectFailure(s.Save);Assert(s.IsConflict&&s.Dirty);Assert(DiarySession.ReadText(s.Target)==external);Assert(File.Exists(s.RecoveryPath));Assert(s.LocalDocument().Contains("中文编辑"));});
        Test("冲突后保留独立 Markdown 草稿再载入磁盘",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);Change(s);s.ReloadKeepingDraft();Assert(!s.Dirty);Assert(Directory.GetFiles(Path.Combine(c.UserDataPath,"recovery"),"*.md").Length==1);Assert(DiarySession.ReadText(s.Target)==s.Baseline);});
        Test("已存在文件被删除：停止写入，不静默重建",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);Change(s);File.Delete(s.Target);ExpectFailure(s.Save);Assert(!File.Exists(s.Target)&&s.Dirty);});
        Test("未编辑时外部删除：保留当前内容并提示",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);var before=s.Bodies[First(s)];File.Delete(s.Target);ExpectFailure(()=>s.ReloadExternal());Assert(s.Bodies[First(s)]==before&&!File.Exists(s.Target));});
        Test("文件被占用：失败保留输入，释放后可重试",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);Change(s);using(var locked=new FileStream(s.Target,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){ExpectFailure(s.Save);Assert(s.Dirty&&File.Exists(s.RecoveryPath));}s.Save();Assert(!s.Dirty&&DiarySession.ReadText(s.Target).Contains("中文编辑"));});
        Test("只读文件：失败提示原因且正文不变",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);var before=DiarySession.ReadText(s.Target);Change(s);File.SetAttributes(s.Target,FileAttributes.ReadOnly);try{ExpectFailure(s.Save);Assert(s.Dirty&&s.Error!=null);Assert(DiarySession.ReadText(s.Target)==before);}finally{File.SetAttributes(s.Target,FileAttributes.Normal);}});
        Test("未保存草稿：新会话恢复原输入",()=>{var c=Fixture();var s=new DiarySession(c,date);Change(s,"草稿待恢复\n");s.PersistDraft();var again=new DiarySession(c,date);Assert(again.Restored&&again.Dirty&&again.Bodies[First(s)].Contains("草稿待恢复"));});
        Test("跨天：旧会话始终写旧路径，新日不携带旧正文",()=>{var c=Fixture();var old=new DiarySession(c,date);Change(old,"前日内容专有\n");old.Save();var next=new DiarySession(c,date.AddDays(1));Assert(!File.Exists(next.Target));Change(next,"新日内容专有\n");next.Save();Assert(DiarySession.ReadText(old.Target).Contains("前日内容专有"));Assert(!DiarySession.ReadText(next.Target).Contains("前日内容专有"));Assert(DiarySession.ReadText(next.Target).Contains("journal_date: \"2026-10-25\""));});
        Test("外部重复栏目：停止保存",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);Change(s);var disk=s.Baseline+"\n## 每日任务完成情况\n重复\n";File.WriteAllText(s.Target,disk,new UTF8Encoding(false));ExpectFailure(s.Save);Assert(DiarySession.ReadText(s.Target)==disk);});
        Test("UTF-8 BOM 与 CRLF 保留",()=>{var c=Fixture();Seed(c,"\uFEFF"+real.Replace("\r\n","\n").Replace("{{date:YYYY-MM-DD}}","2026-10-24").Replace("\n","\r\n"));var s=new DiarySession(c,date);Change(s,"中文\r\n");s.Save();var bytes=File.ReadAllBytes(s.Target);Assert(bytes.Take(3).SequenceEqual(new byte[]{239,187,191}));Assert(DiarySession.ReadText(s.Target).Contains("\r\n"));});
        Test("缺少栏目：仅追加被编辑栏目，其他原文保留",()=>{var c=Fixture();Seed(c,"---\ntype: diary\ncustom: 原文\n---\n# 保留标题\n\n## 额外栏目\n现有\n");var s=new DiarySession(c,date);Change(s);s.Save();var text=DiarySession.ReadText(s.Target);Assert(text.StartsWith("---\ntype: diary\ncustom: 原文"));Assert(text.Contains("## 每日任务完成情况"));Assert(!text.Contains("## 今天推进了什么"));});
        Test("任务区标记误删：拒绝保存并保留原文件",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);s.Edit(First(s),s.Bodies[First(s)].Replace("<!-- TASKS:START -->",""));ExpectFailure(s.Save);Assert(DiarySession.ReadText(s.Target).Contains("<!-- TASKS:START -->"));});
        Test("同时由外部创建当天文件：不覆盖对方的同栏内容",()=>{var c=Fixture();var s=new DiarySession(c,date);Change(s);Seed(c,real.Replace("{{date:YYYY-MM-DD}}","2026-10-24").Replace("前一天规划的任务会自动放在这里","外部已写入的独有内容"));var disk=DiarySession.ReadText(s.Target);ExpectFailure(s.Save);Assert(DiarySession.ReadText(s.Target)==disk);});
        Test("模板动态新增栏目",()=>{var c=Fixture();File.AppendAllText(c.TemplatePath,"\n## 新增的自定义栏目\n提示\n");var s=new DiarySession(c,date);Assert(s.Template.Count==expectedTitles.Length+1&&s.Bodies.ContainsKey("新增的自定义栏目"));});
        Test("外部只改 YAML：不清空用户属性",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);Change(s);File.WriteAllText(s.Target,s.Baseline!.Replace("date: \"2026-10-24\"","date: \"2026-10-23\""),new UTF8Encoding(false));s.Save();Assert(DiarySession.ReadText(s.Target).Contains("date: \"2026-10-23\""));});
        Test("已有笔记不编辑：字节保持不变",()=>{var c=Fixture();Seed(c);var before=File.ReadAllBytes(c.PathFor(date));var s=new DiarySession(c,date);s.Save();Assert(File.ReadAllBytes(s.Target).SequenceEqual(before));});
        Test("外部改为无效 UTF-8：显示编码错误且不覆盖",()=>{var c=Fixture();Seed(c);var s=new DiarySession(c,date);Change(s);var bytes=new byte[]{255,254,128,129};File.WriteAllBytes(s.Target,bytes);ExpectFailure(s.Save);Assert(File.ReadAllBytes(s.Target).SequenceEqual(bytes)&&s.Dirty&&s.Error!.Contains("UTF-8"));});
        const string templateBefore="---\ncustom: 原属性\n---\n## 甲\n旧提示\n\n## 乙\n第二栏\n\n";
        const string templateAfter="---\ncustom: 新模板属性\n---\n## 乙\n第二栏\n\n## 甲（项目）\n新提示\n\n## 丙\n新增提示\n\n";
        void SetTemplate(CardConfig c,string value)=>File.WriteAllText(c.TemplatePath,value,Utf8NoBom());
        UTF8Encoding Utf8NoBom()=>new(false);
        Test("模板更新：新增及重排栏目，未编辑当天不创建文件",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);SetTemplate(c,templateAfter);Assert(s.ReloadTemplate());Assert(s.Template.Select(h=>h.Title).SequenceEqual(new[]{"乙","甲（项目）","丙"}));Assert(!File.Exists(s.Target)&&!s.Dirty);});
        Test("模板更新：更新提示与明确改名，保留正文和原属性",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲",s.Bodies["甲"]+"用户已写中文。\n");s.Save();SetTemplate(c,templateAfter);s.ReloadTemplate();var disk=DiarySession.ReadText(s.Target);Assert(s.Bodies["甲（项目）"].Contains("新提示")&&s.Bodies["甲（项目）"].Contains("用户已写中文"));Assert(disk.Contains("custom: 原属性")&&!disk.Contains("新模板属性"));Assert(new MarkdownDoc(disk).Unique("甲")==null&&new MarkdownDoc(disk).Unique("丙")!=null);});
        Test("模板更新：用户改过的提示不被新模板覆盖",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲","我的自定义正文\n");s.Save();SetTemplate(c,templateBefore.Replace("旧提示","新提示"));s.ReloadTemplate();Assert(s.Bodies["甲"]=="我的自定义正文\n"&&s.TemplateNotice.Contains("保持原样"));});
        Test("模板更新：不把用户代码中的相同字句误当模板提示",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);const string text="用户自己的说明\n```md\n旧提示\n```\n";s.Edit("甲",text);s.Save();SetTemplate(c,templateBefore.Replace("旧提示","新提示"));s.ReloadTemplate();Assert(s.Bodies["甲"]==text);});
        Test("模板更新：删除或不明确改名的栏目保留原文",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲","不得丢失的旧栏内容\n");s.Save();SetTemplate(c,"## 乙\n第二栏\n## 新名字\n新提示\n");s.ReloadTemplate();Assert(!s.Bodies.ContainsKey("甲")&&s.ExtraSections.Any(h=>h.Title=="甲"&&h.Body.Contains("不得丢失")));});
        Test("模板更新：重复标题拒绝应用，未保存输入不丢失",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲","待保存输入\n");SetTemplate(c,"## 重复\n甲\n## 重复\n乙\n");ExpectFailure(()=>s.ReloadTemplate());Assert(s.Dirty&&s.Bodies["甲"].Contains("待保存")&&!File.Exists(s.Target));});
        Test("模板更新：文件占用时保留旧会话，解除后可重试",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲","用户输入\n");s.Save();SetTemplate(c,templateAfter);using(var file=new FileStream(s.Target,FileMode.Open,FileAccess.ReadWrite,FileShare.None))ExpectFailure(()=>s.ReloadTemplate());Assert(s.Bodies.ContainsKey("甲"));s.ReloadTemplate();Assert(s.Bodies["甲（项目）"].Contains("用户输入"));});
        Test("模板更新：合并外部最新正文和属性",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲",s.Bodies["甲"]+"原输入\n");s.Save();File.WriteAllText(s.Target,s.Baseline!.Replace("第二栏","外部最新内容").Replace("custom: 原属性","custom: 外部属性"));SetTemplate(c,templateAfter);s.ReloadTemplate();var disk=DiarySession.ReadText(s.Target);Assert(disk.Contains("外部最新内容")&&disk.Contains("custom: 外部属性")&&disk.Contains("原输入"));});
        Test("模板更新：重启使用缓存匹配旧模板并保留正文",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲",s.Bodies["甲"]+"重启保留\n");s.Save();SetTemplate(c,templateAfter);var restarted=new DiarySession(c,date);Assert(restarted.Bodies["甲（项目）"].Contains("重启保留")&&DiarySession.ReadText(restarted.TemplateCachePath)==templateAfter);});
        Test("模板更新：未保存草稿随模板切换安全恢复",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲",s.Bodies["甲"]+"草稿独有中文\n");s.PersistDraft();SetTemplate(c,templateAfter);var restarted=new DiarySession(c,date);Assert(restarted.Bodies["甲（项目）"].Contains("草稿独有中文")&&File.Exists(restarted.Target));});
        Test("模板更新：没有旧模板缓存时也不丢草稿旧栏目",()=>{var c=Fixture();SetTemplate(c,templateBefore);var s=new DiarySession(c,date);s.Edit("甲","旧版待保存草稿\n");s.PersistDraft();File.Delete(s.TemplateCachePath);SetTemplate(c,templateAfter);var restarted=new DiarySession(c,date);Assert(restarted.Bodies.Values.Any(b=>b.Contains("旧版待保存"))||restarted.ExtraSections.Any(h=>h.Body.Contains("旧版待保存")));});
        Test("模板更新：任务状态与内部承接标记完整保留",()=>{var c=Fixture();var old="## 任务\n旧提示\n<!-- TASKS:START -->\n<!-- TASKS:END -->\n";SetTemplate(c,old);var s=new DiarySession(c,date);s.Edit("任务",s.Bodies["任务"].Replace("<!-- TASKS:END -->","- [x] 已完成 <!-- dailynote-task:sample -->\n<!-- dailynote-seen:sample -->\n<!-- TASKS:END -->"));s.Save();SetTemplate(c,old.Replace("旧提示","新提示"));s.ReloadTemplate();Assert(s.Bodies["任务"].Contains("新提示")&&s.Bodies["任务"].Contains("- [x] 已完成 <!-- dailynote-task:sample -->")&&s.Bodies["任务"].Contains("<!-- dailynote-seen:sample -->"));});
        Test("地址映射：旧绝对配置定位迁移后的仓库和本机数据",()=>{var c=Fixture();Seed(c);string old=Path.Combine(root,"旧地址"),oldData=Path.Combine(old,"local");var input=new CardConfig{VaultPath=old,TemplatePath=Path.Combine(old,"模板","真实模板.md"),DiaryFolder=Path.Combine(old,"日记"),UserDataPath=oldData,PathMappings=new(){{old,c.VaultPath}}};File.WriteAllText(c.ConfigPath,JsonSerializer.Serialize(input,CardConfig.Json));var loaded=CardConfig.Load(c.ConfigPath);var prior=File.ReadAllBytes(c.PathFor(date));var session=new DiarySession(loaded,date);Assert(loaded.VaultPath==c.VaultPath&&loaded.UserDataPath==c.UserDataPath&&session.Target==c.PathFor(date)&&File.ReadAllBytes(session.Target).SequenceEqual(prior));});
        Test("地址映射：仅匹配目录边界，优先最具体路径，原笔记路径不变",()=>{var c=Fixture();string old=Path.Combine(root,"旧地址"),other=Path.Combine(root,"其他");c.PathMappings=new(){{old,other},{Path.Combine(old,"special"),c.VaultPath}};Assert(c.ResolvePath(Path.Combine(old,"special","a.md"),root)==Path.Combine(c.VaultPath,"a.md"));Assert(c.ResolvePath(old+"-副本",root)==old+"-副本");Assert(c.ResolvePath(@"E:\DailyNote\日记\2026\10\2026-10-26.md",root)==@"E:\DailyNote\日记\2026\10\2026-10-26.md");});
        Test("地址映射：相对目标以配置文件目录为基准",()=>{var c=Fixture();string old=Path.Combine(root,"旧地址");c.PathMappings=new(){{old,"."}};Assert(c.ResolvePath(Path.Combine(old,"模板","真实模板.md"),root)==c.TemplatePath);});
        Test("地址映射：迁移前散列命名的待保存草稿与模板缓存恢复",()=>{var c=Fixture();string old=Path.Combine(root,"迁移前"),oldTarget=Path.Combine(old,Path.GetRelativePath(c.VaultPath,c.PathFor(date))),oldTemplate=Path.Combine(old,Path.GetRelativePath(c.VaultPath,c.TemplatePath));SetTemplate(c,templateBefore);Seed(c,templateBefore);Directory.CreateDirectory(Path.Combine(c.UserDataPath,"recovery"));Directory.CreateDirectory(Path.Combine(c.UserDataPath,"templates"));File.WriteAllText(Path.Combine(c.UserDataPath,"templates",DiarySession.Hash(oldTemplate.ToUpperInvariant())[..24]+".md"),templateBefore);var draft=new Draft{Target=oldTarget,Date=date.ToString("yyyy-MM-dd"),Baseline=templateBefore,Bodies=new(){{"甲","迁移草稿中文\n"},{"乙","第二栏\n\n"}},Pending=true};File.WriteAllText(Path.Combine(c.UserDataPath,"recovery",DiarySession.Hash(oldTarget.ToUpperInvariant())[..24]+".json"),JsonSerializer.Serialize(draft,CardConfig.Json));c.PathMappings=new(){{old,c.VaultPath}};SetTemplate(c,templateAfter);var restored=new DiarySession(c,date);Assert(restored.Bodies["甲（项目）"].Contains("迁移草稿中文")&&File.Exists(restored.RecoveryPath)&&DiarySession.ReadText(restored.TemplateCachePath)==templateAfter);});
        Test("只读核验真实模板未改变",()=>Assert(DiarySession.Hash(DiarySession.ReadText(template))==originalHash));
        var report=new {passed=results.Count-failures,failed=failures,template,templateHash=originalHash,finishedAt=DateTime.Now,results};
        File.WriteAllText(Path.Combine(root,"verification.json"),JsonSerializer.Serialize(report,CardConfig.Json));return failures==0?0:1;
    }
}
